import csv
with open('doc/molecule.md') as f: md = f.read()
import re
carcinogenic = set()
for m in re.finditer(r'(TR\d{3}).*?carcinogenic', md, re.I):
    carcinogenic.add(m.group(1))
for m in re.finditer(r'(TR\d{3}).*?positive', md, re.I):
    carcinogenic.add(m.group(1))
with open('csv/atom.csv') as f:
    atoms = list(csv.DictReader(f))
result = {}
for a in atoms:
    mid = a['molecule_id']
    aid = a['atom_id']
    if mid in carcinogenic and aid.endswith('_4'):
        result[mid] = a['element']
print('4th atom elements:', len(result))
for m in sorted(result.keys())[:10]:
    print(f'{m}: {result[m]}')

